    "description": "新华社加德满都8月19日电（记者张平）“看见西藏”故事分享会19日在尼泊尔首都加德满都举行，全国政协常委、民族和宗教委员会副主任、中国人权研究会常务副会长蒋建国，尼泊尔国家人权委员会主席马加尔，中国驻尼泊尔大使张茂明以及中尼各界人士300多人出席。 蒋建国在致辞中表示，今年是西藏和平解放75周年。75年来，中国共产党和中国政府坚持以生存权发展权为首要基本人权，将促进人的自由全面发展作为最高价值追求，成功走出一条顺应时代潮流、适合本国国情…",
    "content": "新华社加德满都8月19日电（记者张平）“看见西藏”故事分享会19日在尼泊尔首都加德满都举行，全国政协常委、民族和宗教委员会副主任、中国人权研究会常务副会长蒋建国，尼泊尔国家人权委员会主席马加尔，中国驻尼泊尔大使张茂明以及中尼各界人士300多人出席。 蒋建国在致辞中表示，今年是西藏和平解放75周年。75年来，中国共产党和中国政府坚持以生存权发展权为首要基本人权，将促进人的自由全面发展作为最高价值追求，成功走出一条顺应时代潮流、适合本国国情的人权发展道路。“西藏的沧桑巨变，是新时代中国人权事业发展最鲜活、最生动的缩影。…"
