    "content": "新华社巴格达8月19日电（记者李军）伊拉克总理扎伊迪、总统阿米迪和国民议会议长哈勒布西19日分别在首都巴格达会见来访的伊朗伊斯兰议会议长卡利巴夫，就巩固双边关系及缓和地区紧张局势等议题交换意见。 8月19日，在伊拉克巴格达，伊拉克总理扎伊迪（右）会见来访的伊朗伊斯兰议会议长卡利巴夫。新华社发（伊拉克总理新闻办公室供图） 根据伊拉克总理新闻办公室发表的声明，扎伊迪在会见时强调了两国在历史、地理和宗教上的深厚渊源，赞赏伊朗对伊拉克的支持，特别是在打击极端组织“伊斯兰国”战争中所给予的帮助。 伊拉克国民议会发表声明说，哈…"
