    "content": "新华社华盛顿8月19日电（记者黄强 徐剑梅）美国总统特朗普19日在白宫对媒体表示，他预计今年晚些时候将会见朝鲜领导人金正恩。 特朗普当天视察了正在白宫南草坪新建的直升机停机坪工地。被问及今秋是否会与金正恩会晤时，特朗普作出肯定回答，并称“非常了解金正恩”，“同他相处得很好”。 据美国《华尔街日报》18日报道，特朗普正敦促助手推动最早在今年秋季与金正恩举行会晤，时间可能选在11月。 特朗普16日在社交媒体发文说，考虑到他与金正恩有着“非常良好的关系”，他对于“美国很久以前同意参加与韩国的联合军演”感到不满，表示已要求…"
