    "content": "新华社基辅8月19日电（记者李东旭）据乌克兰总统网站19日消息，乌克兰总统泽连斯基当天签署法令，解除乌总统办公室副主任伊琳娜·穆德拉职务。网站未说明解职原因。 据乌克兰国际文传电讯社19日报道，乌国家反腐败局和特别反腐败检察官办公室18日曝光一起“天价”保释金洗钱案，涉案嫌疑人中包括乌总统办公室一名副主任、前乌最高拉达（议会）议员、乌国有银行负责人等。上述人员将利用犯罪手段获取的资金通过多个空壳公司为一名代号“米达斯”的乌能源系统巨额腐败案嫌疑人支付了1.5亿格里夫纳（约合340万美元）保释金。 乌议员贡恰连科当天…"
