    "content": "新华社首尔8月19日电（记者张粲）中共中央政治局委员、外交部长王毅19日在首尔同韩国外长赵显举行会谈。 王毅表示，中韩隔海相望，理应经常交往，增进互信，深化合作。去年底以来，习近平主席和李在明总统成功实现互访，就中韩关系未来发展达成重要共识，为两国关系作出战略指引。中韩关系正在按照两国元首指明的方向持续改善和发展。当前世界百年变局加速演进，特别是今年以来，国际形势剧烈动荡，局部冲突加剧蔓延，不仅冲击全球产业链供应链安全，也给地区和平稳定带来消极影响。中韩作为永远的友好邻邦、持久的合作伙伴，应展现战略眼光，着眼两国长…"
