    "author": "陈爱平",
    "description": "新华社上海8月19日电（记者陈爱平）今年8月19日是农历七月初七，是我国传统佳节中的七夕。在上海天文馆（上海科技馆分馆）内，一场主题为“星河为媒”的天文诗会活动上，人们通过中国诗文领略古人的科学与浪漫。 走进上海天文馆光学天象厅，上海市民潘亦浩悠然平躺，在全场黑暗环境中观看穹幕上模拟的夏季星空图景，感受诗句“天阶夜色凉如水，卧看牵牛织女星”描绘的浪漫意境。 8月19日，上海天文馆工作人员介绍织女星、牛郎星。新华社发 场馆工作人员介绍说，…",
    "content": "新华社上海8月19日电（记者陈爱平）今年8月19日是农历七月初七，是我国传统佳节中的七夕。在上海天文馆（上海科技馆分馆）内，一场主题为“星河为媒”的天文诗会活动上，人们通过中国诗文领略古人的科学与浪漫。 走进上海天文馆光学天象厅，上海市民潘亦浩悠然平躺，在全场黑暗环境中观看穹幕上模拟的夏季星空图景，感受诗句“天阶夜色凉如水，卧看牵牛织女星”描绘的浪漫意境。 8月19日，上海天文馆工作人员介绍织女星、牛郎星。新华社发 场馆工作人员介绍说，牛郎与织女七夕相会的故事，寄托了古人对于爱情的美好憧憬。实际上，牛郎星与织女星相…"
