    "description": "新华社约翰内斯堡8月19日电（记者白舸）南非独立在线新闻网站18日刊文指出，中国机器人产业的快速发展，为非洲国家在农业、医疗、矿业和制造业等领域提供了重要发展机遇。文章摘要如下： 近年来，中国机器人产业发展成果显著。国际机器人联合会数据显示，2024年中国新安装工业机器人约29.5万台，占全球总量的54%。中国的机器人产业发展模式将长期规划、大规模工业需求、充足研发投入、强大制造能力和庞大市场结合起来，机器人企业可以在汽车工厂、电子工厂…",
    "content": "新华社约翰内斯堡8月19日电（记者白舸）南非独立在线新闻网站18日刊文指出，中国机器人产业的快速发展，为非洲国家在农业、医疗、矿业和制造业等领域提供了重要发展机遇。文章摘要如下： 近年来，中国机器人产业发展成果显著。国际机器人联合会数据显示，2024年中国新安装工业机器人约29.5万台，占全球总量的54%。中国的机器人产业发展模式将长期规划、大规模工业需求、充足研发投入、强大制造能力和庞大市场结合起来，机器人企业可以在汽车工厂、电子工厂、仓库及物流网络等场景中测试产品，由此形成了实验、成本下降、商业化部署之间的快速…"
