    "content": "新华社巴黎8月19日电（记者孙毅）法国外长巴罗19日接受媒体采访时说，以色列国家安全部长本-格维尔近日发表的在加沙地带实施定点清除的言论“不人道”。 巴罗表示，本-格维尔最近的言论“令人无法容忍”，且“不人道”。他还说，法国对本-格维尔实施了制裁。 巴罗曾于5月23日在社交媒体发文宣布，粗暴对待“全球坚韧船队”被扣人员的本-格维尔即日起被禁止入境法国。巴罗谴责针对巴勒斯坦人“令人震惊”且“煽动仇恨与暴力”的言行，称本-格维尔所作所为就属于此类。 据外媒报道，本-格维尔日前在一档播客节目中称，“我认为应该在加沙实施定…"
