    "content": "新华社北京8月19日电 中央气象台19日预报，受南海热带低压和西南季风影响，未来3天，海南岛、广西南部、广东、福建、台湾岛、浙江等地部分地区有暴雨或大暴雨。经综合研判和应急会商，中国气象局启动重大气象灾害（暴雨）四级应急响应。 中央气象台19日18时发布热带低压预报，南海北部热带扰动于19日下午加强为热带低压，17时其中心位于海南文昌偏东方向约270公里的南海北部海面上，预计20日将以每小时5至10公里的速度向偏西方向缓慢移动，穿过海南岛后移入北部湾海面。 中央气象台预计，19日20时至20日20时，海南岛、广西东…"
