    "description": "新华社石家庄8月19日电（记者岳文婷）石家庄市新华区应急管理局8月19日晚发布通报称：2026年8月19日5时42分，新华区某小区一四层居民楼一个单元的两户房屋发生部分坍塌。事故发生后，公安、消防、住建、应急等相关部门第一时间赶赴现场开展应急救援。截至目前，现场搜救工作已结束，被困人员已被救出。两户房屋共有住户4人，其中3人经送医抢救无效死亡，1人正在全力救治，生命体征平稳。周围住户有5人反映有就医需求，经医院检查无碍已离院。 经初步排…",
    "content": "新华社石家庄8月19日电（记者岳文婷）石家庄市新华区应急管理局8月19日晚发布通报称：2026年8月19日5时42分，新华区某小区一四层居民楼一个单元的两户房屋发生部分坍塌。事故发生后，公安、消防、住建、应急等相关部门第一时间赶赴现场开展应急救援。截至目前，现场搜救工作已结束，被困人员已被救出。两户房屋共有住户4人，其中3人经送医抢救无效死亡，1人正在全力救治，生命体征平稳。周围住户有5人反映有就医需求，经医院检查无碍已离院。 经初步排查，疑似燃气泄漏引发燃爆造成房屋部分坍塌。目前该居民楼及周边住户均已得到妥善安置…"
