    "content": "新华社天津8月19日电 中共中央政治局委员、国务院副总理刘国中8月19日在天津调研。他强调，要深入学习贯彻习近平总书记关于健康中国建设的重要论述精神，坚定不移走中国特色卫生与健康发展道路，坚定不移贯彻新时代卫生与健康工作方针，坚持健康优先发展战略，建设优质高效医疗服务体系，推动脑机接口等卫生健康领域新质生产力发展，更好满足人民群众全方位全周期健康需求。 刘国中先后来到社区卫生服务中心、专科和综合医院，详细了解基层医疗服务、临床专科建设、紧急医学救援队伍建设、血液供应保障等情况。他强调，要深入实施医疗卫生强基工程，加…"
