    "author": "林威",
    "description": "新华社渥太华8月19日电 新闻分析｜从特朗普推迟对加加征关税看北美产业压力 新华社记者林威 美国总统特朗普18日宣布，推迟三天对加拿大商品加征50%关税。加拿大总理卡尼也确认了这一消息。 这一关税原定于当地时间19日正式生效，涉及价值约200亿美元的加拿大商品。最后时限前几个小时，特朗普在社交媒体“真实社交”发文说，美加已达成协议，最终文件内容待敲定。 卡尼当天在一份声明中说，过去数周，加拿大与美国密集磋商、取得进展，但仍有重要工作待完…",
