    "description": "编者按：作为马克思主义建党学说中国化时代化的最新成果，习近平党建思想不仅形成了系统完备的科学体系，更蕴含着坚定的理想信念、高度的历史主动、鲜明的问题导向、强烈的使命担当、深厚的为民情怀、科学的思想方法，具有鲜明的理论品格。为进一步深刻领会习近平党建思想，《天天学习》栏目特别推出系列策划，带您一起走进这些闪耀思想光辉、饱含鲜明品格的历史现场，探寻习近平党建思想的理论源头与实践根基，感悟思想伟力、汲取奋进力量。",
    "content": "编者按：作为马克思主义建党学说中国化时代化的最新成果，习近平党建思想不仅形成了系统完备的科学体系，更蕴含着坚定的理想信念、高度的历史主动、鲜明的问题导向、强烈的使命担当、深厚的为民情怀、科学的思想方法，具有鲜明的理论品格。为进一步深刻领会习近平党建思想，《天天学习》栏目特别推出系列策划，带您一起走进这些闪耀思想光辉、饱含鲜明品格的历史现场，探寻习近平党建思想的理论源头与实践根基，感悟思想伟力、汲取奋进力量。"
