    "description": "受第13号台风“白海豚”残余环流影响，太湖水位持续高位‌，相关部门正全力开展调度排水和抢险工作。8月17日下午，苏州太浦闸重启排水，在保证下游水位平稳的同时降低太湖水位。19日，澎湃新闻记者来到苏州太浦闸，看到太浦闸已10孔全开，每日泄洪5600万方，正在全力排水。",
