    "content": "新华社北京8月19日电 记者8月19日获悉，2026年个人信息保护系列专项行动开展以来，中央网信办、工业和信息化部、公安部会同相关部门强化协调联动，累计对2万余款App、SDK个人信息收集使用情况开展核查检测，督促4000余款完成合规整改，对400余款采取下架等处置处罚措施。 系列专项行动针对个人信息处理规则未明确收集个人信息用于广告、用户画像，未提供个性化广告关闭选项等问题，对1000余家企业和机构的相关产品开展核查检测并督促整改。开展教育、交通、卫生健康、金融等领域个人信息风险排查，累计摸排9万余家企业和机构，…"
