    "content": "中新网8月19日电 据农业农村部网站消息，近日，针对7月以来多轮台风频繁登陆造成长江中下游稻区稻飞虱呈偏重发生态势，农业农村部组织南方水稻主产省会商研判当前稻飞虱发生情况和发展趋势，研究部署稻飞虱统防统治、联防联控工作，及时发布《警惕南方稻区稻飞虱重发风险》提示，组织专家制定《当前水稻稻飞虱防控技术指导意见》。同时，派出工作组和科技小分队赴重点省份指导各地抓住防控时机，落实关键技术措施，调运调配对路药剂和施药装备，指导重点省份用好中央财政重大病虫害防控资金，大力开展统防统治和联防联控，最大限度降低稻飞虱危害损失，坚…"
