    "content": "36氪获悉，湖南黄金公告，公司正在筹划发行股份购买资产并募集配套资金暨关联交易事项，交易预计构成重大资产重组。为保障此次交易实施，公司拟对交易方案中的配套募集资金规模进行调整：原方案配套募集资金总额不超过10亿元，现拟调增至不超过10.5亿元。公司股票自8月20日开市时起停牌，预计停牌不超5个交易日。"
