    "content": "8月22日至26日，第二届世界人形机器人运动会将在国家速滑馆“冰丝带”举行。作为本届世界人形机器人运动会框架下的足球比赛项目，“RCAP亚太机器人世界杯北京大师赛”的预选赛阶段已经在国家速滑馆赛训基地开赛。 本届运动会的机器人足球比赛，共设置5v5大型组和5v5中型组两个组别，并新增了面向全国中学生的3v3 U19组别。来自中国、巴西、印度尼西亚等多个国家的参赛队伍齐聚北京，围绕机器人如何高质量完成足球对抗持续攻关，争取突围到决赛阶段，争夺属于机器人的足球冠军奖杯。 记者：夏子麟、孟菁 新华社音视频部制作 新华社国…"
