    "pub_date": "2026-08-19 20:16:19",
    "author": "",
    "description": "36氪获悉，光大证券披露半年报，2026年上半年，公司实现营业收入60.56亿元，同比增长18.17%；归属于母公司股东的净利润22.29亿元，同比增长32.45%；基本每股收益0.44元。公司拟向全体A股和H股股东每股派送现金股利0.17元（含税），共派发现金股利7.84亿元。",
    "content": "36氪获悉，光大证券披露半年报，2026年上半年，公司实现营业收入60.56亿元，同比增长18.17%；归属于母公司股东的净利润22.29亿元，同比增长32.45%；基本每股收益0.44元。公司拟向全体A股和H股股东每股派送现金股利0.17元（含税），共派发现金股利7.84亿元。"
