    "content": "新华社北京8月19日电 特写｜从“小苹果”到核电站：高温之下的欧洲生活 新华社记者宿亮 今年夏天，法国超市里的蔬果个头比以前小了。 法国商业与零售业联合会18日宣布，法国大型零售商将对水果、蔬菜的大小、外观等采取更加宽容的验收标准。这家商业协会的成员包括家乐福、欧尚、勒克莱尔、安特马尔谢等法国主要零售商。 法国《世界报》报道，家乐福等超市几天前已经公布新措施，允许因缺水导致尺寸不够大、外观不够饱满的水果蔬菜上架销售。例如，原本要求规格达到350克的生菜，现在300克就可以上架售卖。 法国电视一台近期报道，接受采访的…"
